import Utils from "../Utils/Utils";
export default H => {
	H.seriesType('venns', 'venn', {
		states: {
			inactive: false
		},
		dataLabels: {
			enabled: true,
			def: false,
			format: '{point.index}',
			allowOverlap: true,
			style: {
				'textOutline': 'none'
			}
		}
	}, {


		alignDataLabel: function (point, dataLabel, options, alignTo, isNew) {
			let bbox = dataLabel.getBBox();
			dataLabel.attr({
				x: point.plotX - bbox.width / 2,
				y: point.plotY - bbox.height / 2
			})
		},

		render: function () {
			H.seriesTypes.venn.prototype.render.call(this);
			this.applyScale();
		},

		drawPoints: function () {
			let series = this,
				chart = series.chart;

			this.points.forEach(p => {

				if (p.options.name) {
					let legendItemAttr = {
						text: p.options.name,
						x: 0,
						y: 0,
						translateX: p.options.position[0],
						translateY: p.options.position[1],
						rotation: 0
					},
						legendItemStyle = chart.options.legend.itemStyle;

					legendItemStyle['text-anchor'] = p.options.position[2];
					legendItemStyle['dominant-baseline'] = p.options.position[3];

					if (legendItemStyle['dominant-baseline'] === 'auto') {
						legendItemAttr.translateY -= 5;
					}

					if (p.options.position.length > 4) {
						legendItemAttr.rotation = p.options.position[4]
					}
					if (p.legendText) {
						p.legendText.attr(legendItemAttr).css(legendItemStyle);
						for (let key in legendItemStyle) {
							p.legendText.element.style[key] = legendItemStyle[key];
						}
					} else {
						p.legendText = chart.renderer.text().attr(legendItemAttr).css(legendItemStyle).add(series.group)
					}
				} else if (p.legendText) {
					p.legendText = p.legendText.destroy();
				}

				if (p.graphic) {
					p.graphic.attr({
						fill: p.options.color,
						d: p.options.path.split(',')
					});


				} else {
					p.graphic = chart.renderer.path(p.options.path.split(','))
						.attr({
							fill: p.options.color
						}).add(series.group);

				}


				let bbox = p.graphic.getBBox();
				p.plotX = bbox.x + bbox.width / 2;
				p.plotY = bbox.y + bbox.height / 2;
			});

		},

		applyScale() {
			let size = this.options._size,
				viewBox = this.options._viewBox;

			let scale = Utils.min(size.width / viewBox[0], size.height / viewBox[1]);
			size.scale = scale;

			let margin = size.margin * 2;
			size.viewBox = [
				viewBox[0] + margin,
				viewBox[1] + margin
			];

			let seriesGroupAttr = this.options._vennIndex === 3 ? {
				rotationOriginX: size.viewBox[0] / 2,
				rotationOriginY: size.viewBox[1] / 2,
				rotation: 0
			} : {
				rotation: 0
			};

			let translateX = size.margin,
				translateY = size.margin + size.titleOffset;

			seriesGroupAttr.translateX = translateX;
			seriesGroupAttr.translateY = translateY;

			this.group.attr(seriesGroupAttr);
			this.dataLabelsGroup.attr(seriesGroupAttr);
			this.chart.renderer.box.setAttribute('viewBox', `0 0 ${size.viewBox.join(' ')}`);
			if(this.chart.title.alignValue === 'center') {
				console.log(this.chart.title);
				this.chart.title.attr({
					x: size.viewBox[0] /2
				})
			}
		}




	}, {

		destroyElements: function (kinds) {
			if (this.legendText) {
				this.legendText = this.legendText.destroy();
			}
			H.seriesTypes.venn.prototype.pointClass.prototype.__proto__.destroyElements.call(this, kinds);
		}
	})
}