import Chart from "./Chart";

class Scatter extends Chart {

	beforeInit() {

		this.defaultOptions = {
			chart: {
				inverted: true,
				plotBorderWidth: 1,
				plotBorderColor: '#000'
			},
			xAxis: {
				tickInterval: 1,
				lineWidth: 1,
				lineColor: '#000',
				tickLength: 5,
				tickWidth: 1,
				tickColor: '#000',
				reversed: false,
				labels: {
					allowOverlap: true,
					maxStaggerLines: 1,
					padding: 2,
					overflow: 'allow',

					style: {
						"color": "#666666", "cursor": "default", "fontSize": "11px",
						textOverflow: 'none'
					}
				},
				title: {
					x: -20,
					style: {
						fontSize: '12px',
						color: '#666'
					}
				},
				gridLineWidth: 1,
				type: 'category'
			},

			yAxis: {
				lineWidth: 1,
				lineColor: '#000',
				gridLineWidth: 0,
				tickLength: 5,
				tickWidth: 1,
				tickColor: '#000',
				gridLineWidth: 1,
				title: {
					style: {
						fontSize: '12px',
						color: '#666'
					}
				},
				labels: {
					style: { "color": "#666666", "cursor": "default", "fontSize": "11px" }
				}
			},
			colorAxis: {
				reversed: false,
				labels: {
					format: '{value:.2f}',
					style: {
						fontSize: '10px'
					}
				}
			},
			legend: {
				layout: 'vertical',
				align: 'right',
				verticalAlign: 'top',
				y: 20,
				bubbleLegend: {
					sizeBy: 'width',
					connectorDistance: 0,
					color: '#000',
					borderWidth: 0,
					enabled: true,
					labels: {
						align: 'right',
						allowOverlap: true,
						x: 15
					}
				}
			},

			plotOptions: {
				bub: {
					// keys: ['x', 'y', 'z', 'qValue'],
					maxSize: 20,
					minSize: 2,
					states: {
						inactive: false
					}
				}
			},
			title: {
				style: { "color": "#333333", "fontSize": "18px" }
			}
		};

		// this.dataMaping = [
		// 	'richRatio',
		// 	'geneNumber',
		// 	'qValue'
		// ];
	}

	setOptions(options, isDefaultOptions) {
		super.setOptions(options, isDefaultOptions);
		this.options.xAxis.min = 0;
		this.options.xAxis.max = this.options.series[0].data.length -1;
	}

	update(key, value, isDefaultOptions) {
		if (typeof key === 'object') {
			this.chart.update(key);
		} else {
			super.update(key, value, isDefaultOptions);
		}
	}

}

export default Scatter;